Definition rs_W4 (lo : Z) (sp : word) (P stb out n : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp + -96); (stb, stb + SZ_SPCI_STATE); (P + 464, P + 488); (out, out + n); (P + 432, P + 440)]%Z.

Definition rs_read1_post (rax : word) (sp : word) (gp tp : word) (tot P : Z) (s8 s9 s10 s11 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (lo stb implb nr nb : Z) (LB : list block) (Fs : fbv) (sds junk : list byte)
    (FB : fbv) (n : Z) (j8 : list byte) (j7 : list byte) (s7v s6v s5v s4v s3v s2v s1v s0v ra : word)
    : machine_state -> Prop :=
  fun ms' => exists rax' t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' m',
    let k := rs_take sds n in
    ms' = MS (mkR rax' (Z_to_bv 64 (bv_unsigned sp + -128)) gp tp t0' t1' t2' (wz tot) (wz (P + O_H_EC)) (wz (rs_iseof sds)) a1' a2' a3' a4' a5' a6' a7'
                   (wz P) (wz (P + O_H_FB)) (wz (P + O_H_STREAM)) (wz k) (wz G_MISC_CAT_INST) (wz CAT_ID_SYSGEN_SHR1) s8 s9 s10 s11 t3' t4' t5' t6')
              F (Z_to_bv 64 RS_CMP) fc None m' (seg_rom usegs)
    /\ munch (rs_W4 lo sp P stb (fb_out FB) n) m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp + -128)
    /\ StateBlock LB m' stb (P + O_H_IOC) implb (rs_state (mkST (mkSPC VP_SPCI_STATE 1 1 1) 0 Fs STREAM_EOF nr nb) sds n) (skipn (Z.to_nat k) sds)
    /\ rw_cells usegs m' (fb_out FB) [CB (Z.to_nat k) (firstn (Z.to_nat k) sds); CB (Z.to_nat (n - k)) (skipn (Z.to_nat k) junk)]
    /\ rw_cells usegs m' (P + O_H_EC) (ErrCodeCells (if zlength sds =? 0 then EC_ts_eof else EC_clear))
    /\ rw_cells usegs m' (P + O_H_FB) (FlatBufCells (mkFB (fb_begin FB) (fb_in FB) (fb_out FB + k) (fb_last FB) (fb_end FB)))
    /\ XStatics m' /\ MiscVt48 m'
    /\ rw_cells usegs m' (bv_unsigned sp + -128) [CB 8 j8]
    /\ rw_cells usegs m' (bv_unsigned sp + -120) (ErrCodeCells EC_asio_eof)
    /\ rw_cells usegs m' (bv_unsigned sp + -96) [CB 1 [b8 1]; CB 7 j7; C8 (wz (fb_out FB)); C8 (wz n)]
    /\ rw_cells usegs m' (bv_unsigned sp + -72) (map C8 (rs_sv s7v s6v s5v s4v s3v s2v s1v s0v ra))
    /\ rw_cells usegs m' (P + O_H_STREAM) (BasicStreamCells stb).

Definition rs_read1_stmt : Prop :=
  forall rax sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s5x s6x s7x s8 s9 s10 s11 s0v s1v s2v s3v s4v s5v s6v s7v ra t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo P tot stb implb nr nb n : Z) (LB : list block) (Fs FB : fbv) (sds junk j8 j7 : list byte) (t1c : list cell),
  (* [comment removed for export] *)
  rw_cells usegs m (P + O_H_FB) (FlatBufCells FB) -> fb_last FB = fb_out FB + n ->
  0 <= fb_begin FB -> fb_begin FB <= fb_in FB -> fb_in FB <= fb_out FB -> fb_last FB <= fb_end FB -> fb_end FB <= hceil ->
  rw_cells usegs m (fb_out FB) [CB (Z.to_nat n) junk] -> 512 <= n <= 65536 ->
  (* [comment removed for export] *)
  rw_cells usegs m (bv_unsigned sp + -128) [CB 8 j8] ->
  rw_cells usegs m (bv_unsigned sp + -120) t1c -> cells_size t1c = 24%nat ->
  rw_cells usegs m (bv_unsigned sp + -96) [CB 1 [b8 1]; CB 7 j7; C8 (wz (fb_out FB)); C8 (wz n)] ->
  rw_cells usegs m (bv_unsigned sp + -72) (map C8 (rs_sv s7v s6v s5v s4v s3v s2v s1v s0v ra)) ->
  (* [comment removed for export] *)
  rw_cells usegs m (P + O_H_EC) (ErrCodeCells EC_clear) ->
  rw_cells usegs m (P + O_H_STREAM) (BasicStreamCells stb) ->
  StateBlock LB m stb (P + O_H_IOC) implb (mkST (mkSPC VP_SPCI_STATE 1 1 1) 0 Fs STREAM_EOF nr nb) sds ->
  0 <= nr -> nr + 1 < 2^63 -> 0 <= nb -> nb + zlength sds < 2^63 ->
  (fb_out FB + n <= stb \/ stb + SZ_SPCI_STATE <= fb_out FB) ->
  (fb_out FB + n <= fb_begin Fs \/ fb_end Fs <= fb_out FB) ->
  (fb_out FB + n <= 0x10000 \/ 0xb8000 <= fb_out FB) ->
  (fb_end Fs <= stb \/ stb + SZ_SPCI_STATE <= fb_begin Fs) ->
  XStatics m -> MiscVt48 m ->
  stk usegs m lo (bv_unsigned sp + -128) -> lo + 320 <= bv_unsigned sp -> hceil <= lo -> 0xb8000 <= lo ->
  bv_unsigned sp <= P -> P + 488 <= 2^64 -> P mod 8 = 0 -> bv_unsigned sp mod 8 = 0 -> 0 <= tot < 2^64 ->
  0 < fb_begin FB ->                                         (* [comment removed for export] *)
  mem_inv usegs m ->
  evt usegs (rs_read1_post rax sp gp tp tot P s8 s9 s10 s11 F fc m lo stb implb nr nb LB Fs sds junk FB n j8 j7 s7v s6v s5v s4v s3v s2v s1v s0v ra)
    (rs_ms RS_DBPRET rax sp gp tp t0 t1 t2 tot P a0 a1 a2 a3 a4 a5 a6 a7 s5x s6x s7x s8 s9 s10 s11 t3 t4 t5 t6 F fc m).
