Definition rs_data_stmt : Prop :=
  forall rax sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s5x s6x s7x s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P tot : Z) (FB : fbv) (t2c : list cell),
  rw_cells usegs m (P + O_H_FB) (FlatBufCells FB) ->
  rw_cells usegs m (P + O_H_EC) (ErrCodeCells EC_clear) ->
  rw_cells usegs m (bv_unsigned sp + -96) t2c -> cells_size t2c = 24%nat ->
  0 <= fb_in FB -> fb_in FB <= fb_out FB -> fb_out FB < 2^64 -> bv_unsigned sp <= P -> P + 488 <= 2^64 -> 128 <= bv_unsigned sp ->
  mem_inv usegs m ->
  evt usegs (fun ms' => exists m' j,
        ms' = rs_ms P_BP_PUT (wz RS_PUTRET) sp gp tp t0 t1 t2 tot P (wz P) (wz (fb_in FB)) (wz (fb_size FB)) (wz (P + O_H_EC)) a4 a5 a6 a7
                    s5x s6x s7x s8 s9 s10 s11 t3 t4 t5 t6 F fc m'
        /\ munch [(bv_unsigned sp + -96, bv_unsigned sp + -72)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
        /\ rw_cells usegs m' (bv_unsigned sp + -96) [C8 (wz (fb_in FB)); C8 (wz (fb_size FB)); CB 8 j]
        /\ rw_cells usegs m' (P + O_H_FB) (FlatBufCells FB)
        /\ rw_cells usegs m' (P + O_H_EC) (ErrCodeCells EC_clear))
    (rs_ms RS_CMP rax sp gp tp t0 t1 t2 tot P (wz 0) a1 a2 a3 a4 a5 a6 a7 s5x s6x s7x s8 s9 s10 s11 t3 t4 t5 t6 F fc m).

